  for(const x of [300,540,684,828,972,1050])for(const sg of [-1,1])hull('pd',x,sg*.7,true,'ventral-defence');
  for(const [x,zf] of [[620,.4],[860,.34],[1000,.3]])for(const sg of [-1,1])hull('trc',x,sg*zf,true,'recovery-tractor');
