 craft_vwing:{g:5200,basis:'published acceleration'},
 craft_xwing:{g:3700,basis:'published acceleration'},
 craft_z95:{g:3330,reactors:[1.02,1.02],basis:'game assumption; 90% of X-wing acceleration'}
