 if(B){for(const k in GUN_BANDS){if(d>GUN_BANDS[k].range||!B[k])continue;const g=Math.max(0,fleetArc(u,t,B[k])-(u.dualDefense?fleetArc(u,t,p.dualPurpose?.gunBands?.[k]||[]):0));gun+=g;cost+=g*COMBAT.bandCost[k];}}
