 if(t.p.len>=COMBAT.bigAim*(u.p.len||1)&&(u.p.len||0)<=COMBAT.smallShip){const r=Math.max(t.p.width||t.p.len*.35,t.p.height||t.p.len*.2)*.5+u.p.len*.5+1500;m.set(t.p,r);return r;}
