 const parts=fs.map(f=>{const p=windowBay(f);p.commandRole=FITS[f.k].role;p.host=f.host;p.label=COMMAND_ROLES[p.commandRole]+'区画';p.requiredVolume=p.boxSize.reduce((a,b)=>a*b,1);return p;});
